"""Parse/encode PHP/Rack-style nested query strings.

Examples
--------
>>> parse_qs_nested('a=1&b[c]=2&b[d][]=3&b[d][]=4&e[0]=x&e[1]=y')
{'a': '1', 'b': {'c': '2', 'd': ['3', '4']}, 'e': ['x', 'y']}

Rules:
  * keys and values are percent-decoded ('+' means space)
  * '[]' appends to a list
  * '[N]' indexes a list; indices must arrive dense and in order,
    i.e. the first index must be 0 and each next index must equal
    the current length of the list, otherwise QsError
  * mixing dict and list access under one key is a QsError
    (this includes mixing scalars and containers under one key)
  * a later scalar overwriting an earlier scalar is allowed
"""

from urllib.parse import quote_plus, unquote_plus

__all__ = ["QsError", "parse_qs_nested", "encode"]

_MISSING = object()


class QsError(ValueError):
    """Raised for malformed or conflicting nested query strings."""


def _is_index(token):
    return bool(token) and token.isascii() and token.isdigit()


def _wants_list(next_token):
    """True if the upcoming token addresses a list rather than a dict."""
    return next_token == "" or _is_index(next_token)


def _split_key(raw_key):
    """Split a raw (still percent-encoded) key into bracket tokens.

    Splitting happens *before* decoding so that encoded brackets
    (%5B / %5D) are never mistaken for structure. Malformed tails
    (no closing bracket) become literal parts of the last token,
    mirroring PHP's behaviour.
    """
    i = raw_key.find("[")
    if i == -1:
        return [raw_key]
    tokens = [raw_key[:i]]
    rest = raw_key[i:]
    while rest:
        if not rest.startswith("["):
            tokens[-1] += rest
            break
        j = rest.find("]")
        if j == -1:
            tokens[-1] += rest
            break
        tokens.append(rest[1:j])
        rest = rest[j + 1:]
    return tokens


def _assign(container, tokens, value):
    tok, rest = tokens[0], tokens[1:]

    if isinstance(container, list):
        if tok == "":
            idx = len(container)
        elif _is_index(tok):
            idx = int(tok)
        else:
            raise QsError(f"cannot use dict key {tok!r} on a list")
        if idx != len(container):
            raise QsError(
                "list indices must arrive dense and in order "
                f"(expected {len(container)}, got {idx})"
            )
        if rest:
            child = [] if _wants_list(rest[0]) else {}
            container.append(child)
            _assign(child, rest, value)
        else:
            container.append(value)
        return

    if isinstance(container, dict):
        if rest:
            want_list = _wants_list(rest[0])
            existing = container.get(tok, _MISSING)
            if existing is _MISSING:
                child = [] if want_list else {}
                container[tok] = child
            elif want_list != isinstance(existing, list):
                kind = "list" if want_list else "dict"
                raise QsError(
                    f"mixing dict and list access under key {tok!r}: "
                    f"tried to use {kind} on existing "
                    f"{type(existing).__name__}"
                )
            else:
                child = existing
            _assign(child, rest, value)
        elif tok == "":
            # '[]' as the innermost token: append under the '' key
            lst = container.get(tok, _MISSING)
            if lst is _MISSING:
                container[tok] = [value]
            elif isinstance(lst, list):
                lst.append(value)
            else:
                raise QsError(f"mixing dict and list access under key {tok!r}")
        else:
            existing = container.get(tok, _MISSING)
            if existing is not _MISSING and not isinstance(existing, str):
                raise QsError(
                    f"cannot overwrite container under key {tok!r} with a scalar"
                )
            container[tok] = value  # scalar overwrites scalar: allowed
        return

    raise QsError("cannot descend into a scalar value")


def parse_qs_nested(query_string):
    """Parse a PHP/Rack-style nested query string into dicts/lists of str."""
    root = {}
    if not query_string:
        return root
    for pair in query_string.split("&"):
        if pair == "":
            continue
        if "=" in pair:
            raw_key, raw_value = pair.split("=", 1)
        else:
            raw_key, raw_value = pair, ""
        tokens = [unquote_plus(t) for t in _split_key(raw_key)]
        _assign(root, tokens, unquote_plus(raw_value))
    return root


def _encode(node, prefix, parts):
    if isinstance(node, dict):
        for k, v in node.items():
            key = (
                f"{prefix}[{quote_plus(str(k))}]" if prefix else quote_plus(str(k))
            )
            _encode(v, key, parts)
    elif isinstance(node, (list, tuple)):
        for v in node:
            _encode(v, f"{prefix}[]", parts)
    else:
        parts.append(f"{prefix}={quote_plus(str(node))}")


def encode(obj):
    """Encode nested dicts/lists into a query string (inverse of parse).

    Notes: empty dicts/lists encode to '' (and parse back as {}),
    and dict keys must be non-empty and not purely numeric, otherwise
    the round trip changes the container type.
    """
    parts = []
    _encode(obj, "", parts)
    return "&".join(parts)

