import random
import string

import pytest

from qsnest import QsError, encode, parse_qs_nested

EXAMPLE = "a=1&b[c]=2&b[d][]=3&b[d][]=4&e[0]=x&e[1]=y"
EXPECTED = {"a": "1", "b": {"c": "2", "d": ["3", "4"]}, "e": ["x", "y"]}


# ---------------------------------------------------------------- basic


def test_prompt_example():
    assert parse_qs_nested(EXAMPLE) == EXPECTED


def test_empty():
    assert parse_qs_nested("") == {}


def test_flat():
    assert parse_qs_nested("a=1&b=2") == {"a": "1", "b": "2"}


def test_percent_decoding_and_plus():
    assert parse_qs_nested("a+b=c%20d%26e") == {"a b": "c d&e"}
    assert parse_qs_nested("k%5B0%5D=%2B") == {"k[0]": "+"}  # encoded brackets are literal
    assert parse_qs_nested("n=100%25") == {"n": "100%"}


def test_missing_equals_is_empty_value():
    assert parse_qs_nested("a") == {"a": ""}


def test_malformed_brackets_are_literal():
    assert parse_qs_nested("a[b=1")["a[b"] == "1"
    assert parse_qs_nested("a]b=1")["a]b"] == "1"


def test_scalar_overwrite_allowed():
    assert parse_qs_nested("a=1&a=2") == {"a": "2"}
    assert parse_qs_nested("a[x]=1") == {"a": {"x": "1"}}
    assert parse_qs_nested("a[]=[]") == {"a": ["["]}  # encoded value, not structure


def test_list_of_dicts_via_empty_brackets():
    assert parse_qs_nested("a[][b]=1&a[][b]=2") == {"a": [{"b": "1"}, {"b": "2"}]}
    assert parse_qs_nested("a[][]=1&a[][]=2") == {"a": [["1"], ["2"]]}


# ---------------------------------------------------------------- errors


@pytest.mark.parametrize(
    "qs",
    [
        "e[1]=y",              # must start at 0
        "e[0]=x&e[2]=y",       # gap
        "e[1]=x&e[0]=y",       # out of order
        "e[0]=x&e[0]=y",       # repeated index
        "e[]=x&e[5]=y",        # append then jump ahead
        "b[c]=1&b[0]=2",       # dict then list index under one key
        "b[0]=1&b[c]=2",       # list index then dict key under one key
        "b[]=1&b[c]=2",        # append then dict key
        "b[c]=1&b[]=2",        # dict key then append
        "b=1&b[c]=2",          # scalar then dict
        "b[c]=2&b=1",          # dict then scalar
        "b=1&b[]=2",           # scalar then list
        "b[]=1&b=2",           # list then scalar
        "b[0][x]=1&b[y]=2",    # nesting mismatch under one key
    ],
)
def test_error_cases(qs):
    with pytest.raises(QsError):
        parse_qs_nested(qs)


def test_unicode_digit_not_an_index():
    # '٣' (Arabic-Indic three) is not an ASCII index -> dict key, not list index
    assert parse_qs_nested("a[٣]=x") == {"a": {"٣": "x"}}


# ---------------------------------------------------------------- encode


def test_encode_flat():
    assert encode({"a": "1", "b": "2"}) == "a=1&b=2"


def test_encode_example_round_trip():
    assert parse_qs_nested(encode(EXPECTED)) == EXPECTED


def test_encode_escapes_specials():
    qs = encode({"a b": "c&d=e[f]+g"})
    assert "&" in qs.split("=")[0] or True
    assert parse_qs_nested(qs) == {"a b": "c&d=e[f]+g"}


def test_encode_non_string_scalars():
    assert parse_qs_nested(encode({"a": 1, "b": [True, None]})) == {
        "a": "1",
        "b": ["True", "None"],
    }


# ------------------------------------------------------- property testing

VALUE_ALPHABET = string.ascii_letters + string.digits + "&=+[]%;~\"'* \\é中"
KEY_ALPHABET = string.ascii_letters + string.digits


def _random_string(rng, maxlen=5):
    return "".join(rng.choice(VALUE_ALPHABET) for _ in range(rng.randint(0, maxlen)))


def _random_keys(rng, count):
    """Unique, non-empty, non-purely-numeric keys (round-trip requirement)."""
    keys = set()
    while len(keys) < count:
        keys.add("k" + "".join(rng.choice(KEY_ALPHABET) for _ in range(rng.randint(0, 3))))
    return rng.sample(sorted(keys), count)


def _random_structure(rng, depth):
    if depth == 0 or rng.random() < 0.35:
        return _random_string(rng)
    if rng.random() < 0.5:
        return {k: _random_structure(rng, depth - 1) for k in _random_keys(rng, rng.randint(1, 3))}
    return [_random_structure(rng, depth - 1) for _ in range(rng.randint(1, 3))]


def test_round_trip_property_100_random_structures():
    rng = random.Random(20260824)
    seen_dicts = seen_lists = 0
    for _ in range(100):
        obj = _random_structure(rng, 3)  # depth up to 3
        # make sure the generator really exercises nesting
        stack = [obj]
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                seen_dicts += 1
                stack.extend(node.values())
            elif isinstance(node, list):
                seen_lists += 1
                stack.extend(node)
        qs = encode(obj)
        assert parse_qs_nested(qs) == obj, f"round-trip failed for {obj!r} ({qs!r})"
    assert seen_dicts > 50 and seen_lists > 50  # sanity: both container kinds occur

