* '[]' appends to a list; keyed accesses following '[]' reuse the
  last list element when its type matches (Rack-style), e.g.
  'a[][x]=1&a[][y]=2' -> {'a': [{'x': '1', 'y': '2'}]}

edits.newText:
def test_empty_bracket_and_indexed_list_elements():
    # each '[]'-led access starts a fresh element
    assert parse_qs_nested("a[][b]=1&a[][c]=2") == {"a": [{"b": "1"}, {"c": "2"}]}
    # dense indices share one element
    assert parse_qs_nested("a[0][b]=1&a[0][c]=2") == {"a": [{"b": "1", "c": "2"}]}
    assert parse_qs_nested("a[][]=1&a[][]=2") == {"a": [["1"], ["2"]]}
    assert parse_qs_nested("a[][b][]=1&a[][c][]=2") == {
        "a": [{"b": ["1"]}, {"c": ["2"]}]
    }

