def test_rack_style_merging_after_empty_brackets():
    # consecutive keyed accesses after [] land in the same element
    assert parse_qs_nested("a[][b]=1&a[][c]=2") == {"a": [{"b": "1", "c": "2"}]}
    # a scalar element breaks the run: a new dict element starts after it
    assert parse_qs_nested("a[][b]=1&a[]=2&a[][c]=3") == {
        "a": [{"b": "1"}, "2", {"c": "3"}]
    }
    assert parse_qs_nested("a[][b][]=1&a[][b][]=2") == {"a": [{"b": ["1", "2"]}]}

